package com.cyancoder.aiorchestrator.api;
import com.cyancoder.aiorchestrator.domain.ProjectRelease;import com.cyancoder.aiorchestrator.service.ProjectReleaseService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/endpoint/ai-orchestrator") @PreAuthorize("@platformAuthorizationService.canUseCapability('builder:use')") public class EndpointProjectReleaseController{private final ProjectReleaseService service;public EndpointProjectReleaseController(ProjectReleaseService s){service=s;}public record CreateReleaseRequest(String provisioningRunId){}
 @GetMapping("/drafts/{draftId}/releases") public List<ProjectRelease> list(@PathVariable String draftId,@RequestHeader("X-Tenant-Key") String tenant,@RequestHeader(value="X-Site-Key",required=false)String site){return service.list(draftId,tenant,site);}@GetMapping("/drafts/{draftId}/active-release") public ProjectRelease active(@PathVariable String draftId,@RequestHeader("X-Tenant-Key") String tenant,@RequestHeader(value="X-Site-Key",required=false)String site){return service.active(draftId,tenant,site);}@GetMapping("/releases/{releaseId}") public ProjectRelease get(@PathVariable String releaseId,@RequestHeader("X-Tenant-Key") String tenant,@RequestHeader(value="X-Site-Key",required=false)String site){return service.get(releaseId,tenant,site);}
 @PostMapping("/drafts/{draftId}/releases") public ProjectRelease create(@PathVariable String draftId,@RequestBody CreateReleaseRequest request,Authentication auth,@RequestHeader("X-Tenant-Key") String tenant,@RequestHeader(value="X-Site-Key",required=false)String site){return service.create(draftId,request.provisioningRunId(),auth==null?"endpoint-user":auth.getName(),tenant,site);}@PostMapping("/releases/{releaseId}/publish") public ProjectRelease publish(@PathVariable String releaseId,@RequestHeader("X-Tenant-Key") String tenant,@RequestHeader(value="X-Site-Key",required=false)String site){return service.activate(releaseId,tenant,site);}@PostMapping("/releases/{releaseId}/rollback") public ProjectRelease rollback(@PathVariable String releaseId,@RequestHeader("X-Tenant-Key") String tenant,@RequestHeader(value="X-Site-Key",required=false)String site){return service.activate(releaseId,tenant,site);} }
